package DayProgress;
import java.lang.*;
public class Day4Task14 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//boxing 
		int num=120;
		Integer i=Integer.valueOf(num);
		
		//unboxing
		int num2=i.intValue();
		System.out.println("Integr value :"+i);
		System.out.println("Int value :"+num2);
		
	}

}
